@import url('https://fonts.googleapis.com/css2?family=Barlow+Condensed:wght@600;700;800;900&family=DM+Mono:wght@400;500&family=Inter:wght@400;500;600;700;800&display=swap');
:root{color-scheme:dark;--bg:#10131c;--panel:#171b26;--panel2:#1d2230;--line:#2a3040;--muted:#777f92;--white:#f4f4f0;--blue:#36d9ff;--pink:#ff4d9b;--green:#b7f36b;--mono:'DM Mono',monospace;--display:'Barlow Condensed',Impact,sans-serif;--body:Inter,Arial,sans-serif}
*{box-sizing:border-box}html{min-height:100%;background:var(--bg)}body{margin:0;min-height:100vh;background:radial-gradient(ellipse at 50% 20%,#202638 0,#141823 36%,#10131c 75%);color:var(--white);font-family:var(--body);-webkit-tap-highlight-color:transparent;overscroll-behavior:none}.shell{max-width:1120px;padding:0 40px;margin:auto}.topbar{height:74px;border-bottom:1px solid rgba(255,255,255,.07);display:flex;align-items:center;justify-content:space-between}.brand{display:flex;gap:11px;align-items:center;text-decoration:none;color:var(--white);font-family:var(--display);font-size:21px;font-weight:800;letter-spacing:1px}.brand-light{font-weight:600;color:#a8afbd;margin-left:4px}.brand-mark{width:24px;height:24px;display:flex;align-items:center;gap:3px;transform:skew(-13deg)}.brand-mark span{display:block;width:5px;border-radius:4px;background:var(--green)}.brand-mark span:nth-child(1){height:11px;opacity:.65}.brand-mark span:nth-child(2){height:18px}.brand-mark span:nth-child(3){height:14px;opacity:.8}.top-tag,.eyebrow,.fighter-sub,.round-label,.health-meta,.canvas-hud,.game-footer,.tip-label,.controls-legend,.site-footer,.overlay-kicker,.overlay-foot,.control-button small,.aim-label{font-family:var(--mono);letter-spacing:.08em}.top-tag{color:#929aab;font-size:10px;display:flex;align-items:center;gap:8px}.live-dot,.footer-dot,.hud-live{width:6px;height:6px;background:var(--green);border-radius:50%;box-shadow:0 0 10px #b7f36b88}.tag-divider{color:#465064;margin:0 2px}.icon-button{width:34px;height:34px;border:1px solid #343a49;background:#191e2a;color:#afb6c4;border-radius:8px;cursor:pointer;font-size:18px}.icon-button:hover{border-color:var(--green);color:var(--green)}.intro-row{display:flex;align-items:flex-end;justify-content:space-between;padding:29px 0 21px}.eyebrow{display:flex;align-items:center;gap:9px;color:var(--green);font-size:9px;font-weight:500;letter-spacing:.18em}.eyebrow-line{height:1px;width:19px;background:#54633e}h1{font-family:var(--display);font-weight:900;font-size:clamp(43px,6vw,65px);line-height:.83;letter-spacing:.01em;margin:12px 0 9px}h1 span{color:var(--green)}.intro-copy{margin:0;color:#9aa1ae;font-size:12px;letter-spacing:.015em}.match-note{display:flex;align-items:center;gap:10px;padding-bottom:5px;color:#8e96a7;font:9px/1.6 var(--mono);letter-spacing:.12em}.match-note b{font-size:10px;color:#e5e7e8;font-weight:500}.note-icon{font-size:23px;color:var(--pink)}.game-card{background:linear-gradient(145deg,#191e2b,#161a25);border:1px solid #303747;border-radius:11px;padding:0 22px 0;box-shadow:0 20px 70px #080a0f66;overflow:hidden}.arena-top{height:78px;display:grid;grid-template-columns:1fr 130px 1fr;align-items:center}.fighter{display:flex;align-items:center;gap:10px}.fighter-rival{justify-content:flex-end;text-align:right}.avatar{height:39px;width:39px;border:1px solid;display:grid;place-items:center;position:relative;font:700 18px var(--display);clip-path:polygon(0 0,78% 0,100% 23%,100% 100%,20% 100%,0 79%)}.avatar:after{content:'';position:absolute;inset:4px;border:1px solid currentColor;opacity:.25;clip-path:polygon(0 0,78% 0,100% 23%,100% 100%,20% 100%,0 79%)}.avatar i{position:absolute;width:4px;height:4px;border-radius:50%;right:6px;top:6px;background:currentColor;box-shadow:0 0 7px currentColor}.avatar-you{background:#12303b;color:var(--blue);border-color:#29788a}.avatar-rival{background:#361b2c;color:var(--pink);border-color:#8e315f}.fighter-name{font-family:var(--display);font-size:17px;font-weight:800;letter-spacing:.07em;color:#f0f1f0}.fighter-sub{font-size:8px;color:#737d8f;margin-top:3px;letter-spacing:.1em}.rank-dot{font-size:9px;color:var(--green);vertical-align:2px}.bot-label{font:8px var(--mono);color:var(--pink);border:1px solid #7d3256;padding:2px 4px;vertical-align:2px;letter-spacing:.05em}.scoreboard{text-align:center}.round-label{color:#858c9c;font-size:8px;letter-spacing:.15em}.round-label span{color:var(--green);margin-left:3px}.score-line{font:700 25px var(--display);letter-spacing:.07em;line-height:1.04}.score-you{color:var(--blue)}.score-rival{color:var(--pink)}.score-dash{color:#626b7e;padding:0 6px}.round-pips{display:flex;gap:4px;justify-content:center;margin-top:5px}.pip{width:5px;height:5px;border-radius:50%;background:#353b49}.pip-you{border:1px solid #2a7182}.pip-rival{border:1px solid #7e3157}.pip.won-you{background:var(--blue);box-shadow:0 0 7px #36d9ff88}.pip.won-rival{background:var(--pink);box-shadow:0 0 7px #ff4d9b88}.health-row{position:relative;display:grid;grid-template-columns:1fr 84px 1fr;align-items:center;gap:11px;padding-bottom:9px}.health-track{height:5px;border-radius:8px;background:#2b3040;position:relative;overflow:hidden}.health-fill{height:100%;width:100%;border-radius:inherit;transition:width .15s ease-out}.health-blue{background:linear-gradient(90deg,#1686a3,var(--blue));box-shadow:0 0 11px #36d9ff66}.health-pink{background:linear-gradient(90deg,var(--pink),#b72e70);box-shadow:0 0 11px #ff4d9b66}.health-track-right{display:flex;justify-content:flex-end}.health-track-right .health-fill{margin-left:auto}.health-glint{position:absolute;width:20px;height:1px;left:8px;top:1px;background:#ffffff77}.health-meta{position:absolute;left:0;right:0;top:7px;display:flex;align-items:center;justify-content:space-between;font-size:8px;color:#717a8d;letter-spacing:.06em}.health-meta b{color:#bdc2cc;font-weight:400}.timer{font:500 13px var(--mono);color:var(--green);letter-spacing:.03em}.canvas-wrap{position:relative;width:100%;aspect-ratio:1.96;background:#121927;border:1px solid #343d50;overflow:hidden;touch-action:none}.canvas-wrap canvas{display:block;width:100%;height:100%;touch-action:none}.canvas-hud{position:absolute;left:12px;right:12px;top:10px;display:flex;justify-content:space-between;color:#8f9aab;font-size:8px;pointer-events:none;letter-spacing:.1em}.canvas-hud>span:first-child{display:flex;align-items:center;gap:6px}.hud-live{width:5px;height:5px}.arena-corner{position:absolute;width:9px;height:9px;border-color:#a9f36a;opacity:.8;pointer-events:none}.corner-tl{left:-1px;top:-1px;border-left:1px solid;border-top:1px solid}.corner-tr{right:-1px;top:-1px;border-right:1px solid;border-top:1px solid}.corner-bl{left:-1px;bottom:-1px;border-left:1px solid;border-bottom:1px solid}.corner-br{right:-1px;bottom:-1px;border-right:1px solid;border-bottom:1px solid}.screen-overlay{position:absolute;inset:0;display:grid;place-items:center;background:linear-gradient(90deg,#101722dd 0%,#101722aa 51%,#10172299 100%);transition:opacity .25s ease,visibility .25s}.screen-overlay.hidden{opacity:0;visibility:hidden;pointer-events:none}.overlay-content{width:min(490px,90%);text-align:left;padding:13px 15px 8px;position:relative}.overlay-kicker{font-size:9px;color:var(--green);letter-spacing:.15em;margin-bottom:12px}.overlay-kicker span{color:#697389;margin-right:8px}.overlay-content h2{font:900 clamp(36px,5.7vw,58px)/.8 var(--display);letter-spacing:.02em;margin:0 0 12px}.overlay-content h2 em{font-style:normal;color:var(--green)}.overlay-content p{color:#a6aebc;font-size:11px;line-height:1.7;margin:0 0 17px}.primary-button{display:flex;align-items:center;justify-content:space-between;gap:36px;background:var(--green);color:#182017;border:0;border-radius:4px;padding:12px 14px;min-width:172px;font:800 11px var(--body);letter-spacing:.08em;cursor:pointer;box-shadow:0 5px 25px #b7f36b27;transition:transform .15s,background .15s}.primary-button:hover{transform:translateY(-2px);background:#c9ff7c}.primary-button b{font-size:17px}.overlay-foot{margin-top:19px;font-size:7px;color:#8d97a7;display:flex;align-items:center;gap:5px;letter-spacing:.05em}.keycap,kbd{font-family:var(--mono);font-size:8px;line-height:1;border:1px solid #596171;background:#242a38;color:#d4d8dd;padding:4px 5px;border-radius:3px}.foot-dot{color:var(--green);padding:0 2px}.game-controls{height:82px;display:flex;align-items:center;justify-content:space-between;gap:10px}.move-controls,.aim-controls{display:flex;align-items:center;gap:7px}.control-button{border:1px solid #333b4d;background:#202635;color:#dce1e7;border-radius:7px;cursor:pointer;touch-action:none;user-select:none;-webkit-user-select:none;transition:background .12s,border .12s,transform .12s}.control-button:active,.control-button.pressed{background:#354256;border-color:var(--green);transform:scale(.97)}.move-button{height:48px;width:51px;display:flex;flex-direction:column;justify-content:center;align-items:center;gap:0}.move-button span{font-size:19px;line-height:20px}.control-button small{font-size:6px;color:#9099a8;letter-spacing:.08em}.jump-button{margin-left:4px;border-color:#36414c;background:#202a30}.jump-button span{color:var(--green)}.aim-controls{margin-left:auto}.aim-label{font-size:8px;color:#838c9c;margin-right:2px}.aim-button{height:32px;width:35px;font-size:16px;line-height:1}.fire-button{height:49px;min-width:155px;border:1px solid #a93c6b;border-radius:6px;background:linear-gradient(110deg,#5b2040,#351a31);color:#ffd7e8;display:flex;justify-content:center;align-items:center;gap:9px;font:700 9px var(--mono);letter-spacing:.09em;cursor:pointer;touch-action:none;user-select:none;box-shadow:inset 0 0 18px #ff4d9b0a;transition:.15s}.fire-button .fire-icon{font-size:17px;color:var(--pink)}.fire-button i{position:absolute;display:none}.fire-button:hover,.fire-button.firing{background:linear-gradient(110deg,#9d3267,#5a204e);border-color:#ff75b1;box-shadow:0 0 18px #ff4d9b30}.fire-button.firing .fire-icon{animation:spin .6s linear infinite}.game-footer{height:37px;border-top:1px solid #2b3140;display:flex;align-items:center;justify-content:space-between;color:#737c8f;font-size:8px;letter-spacing:.06em}.game-footer>span:first-child{display:flex;align-items:center;gap:6px}.footer-dot{width:5px;height:5px}.game-footer b{color:#bac1cb;font-weight:400}.pause-button{border:0;background:none;color:#8992a2;font:8px var(--mono);letter-spacing:.08em;cursor:pointer}.pause-button span{color:var(--green);font-size:11px;margin-right:4px}.pause-button:hover{color:white}.latency b{color:var(--green)}.bottom-row{display:flex;justify-content:space-between;align-items:center;gap:15px;margin-top:17px}.tip-card{display:flex;align-items:center;gap:10px}.tip-symbol{font-size:25px;color:var(--pink);transform:rotate(-25deg)}.tip-label,.legend-label{font-size:8px;color:#858e9f;letter-spacing:.12em}.tip-card p{margin:4px 0 0;font-size:10px;color:#aab1be}.tip-card b{color:#eff1f2;font-weight:600}.controls-legend{display:flex;align-items:center;gap:6px;color:#858e9f;font-size:7px;letter-spacing:.04em}.controls-legend .legend-label{margin-right:5px}.controls-legend kbd{padding:4px 5px;margin-right:2px}.site-footer{display:flex;justify-content:space-between;border-top:1px solid #262c39;margin-top:20px;padding:12px 0 17px;color:#626c7d;font-size:7px;letter-spacing:.1em}.site-footer b{color:var(--green);font-size:10px;margin-left:3px}@keyframes spin{to{transform:rotate(360deg)}}
@media(max-width:720px){.shell{padding:0 18px}.topbar{height:58px}.top-tag{font-size:8px}.intro-row{padding:23px 0 16px}.game-card{padding:0 12px}.arena-top{height:66px;grid-template-columns:1fr 86px 1fr}.avatar{height:33px;width:33px}.fighter{gap:7px}.fighter-name{font-size:14px}.fighter-sub{font-size:6px}.round-label{font-size:7px}.score-line{font-size:21px}.health-row{grid-template-columns:1fr 66px 1fr;gap:7px}.health-meta{font-size:7px}.canvas-wrap{aspect-ratio:1.56}.overlay-content{width:94%;padding:5px 6px}.overlay-kicker{margin-bottom:9px}.overlay-content h2{font-size:clamp(36px,8vw,50px)}.overlay-content p{font-size:10px;margin-bottom:12px}.overlay-foot{font-size:6px;gap:3px;margin-top:12px}.keycap{font-size:7px;padding:3px 4px}.game-controls{height:73px}.move-button{height:44px;width:45px}.fire-button{min-width:126px;height:45px;font-size:8px;gap:6px}.aim-controls{gap:5px}.aim-button{width:31px;height:30px}.bottom-row{margin-top:13px}.controls-legend{display:none}.site-footer{font-size:6px;margin-top:14px}}
@media(max-width:430px){.shell{padding:0 11px}.topbar{height:51px}.brand{font-size:18px}.brand-mark{transform:scale(.85) skew(-13deg);margin-right:-3px}.top-tag{font-size:7px;gap:5px}.intro-row{padding:18px 0 13px}h1{font-size:46px}.match-note{font-size:8px}.game-card{padding:0 8px;border-radius:8px}.arena-top{height:61px;grid-template-columns:1fr 70px 1fr}.avatar{height:29px;width:29px;font-size:15px}.fighter{gap:5px}.fighter-name{font-size:12px}.fighter-sub{font-size:5px}.bot-label{font-size:6px;padding:1px 3px}.score-line{font-size:19px}.health-row{grid-template-columns:1fr 58px 1fr;gap:5px}.health-meta{font-size:6px}.timer{font-size:11px}.canvas-wrap{aspect-ratio:1.35}.canvas-hud{top:7px;left:8px;right:8px;font-size:6px}.overlay-content h2{font-size:37px}.overlay-content p{font-size:9px}.overlay-foot{font-size:5.5px;gap:2px;letter-spacing:0}.keycap{font-size:6px;padding:3px}.primary-button{padding:10px 12px;min-width:152px}.game-controls{height:66px;gap:5px}.move-controls{gap:4px}.move-button{width:39px;height:41px}.move-button span{font-size:16px}.control-button small{font-size:5px}.jump-button{margin-left:1px}.aim-controls{gap:4px}.aim-label{font-size:6px;margin-right:0}.aim-button{height:29px;width:27px}.fire-button{height:42px;min-width:106px;font-size:7px;gap:5px}.fire-button .fire-icon{font-size:14px}.game-footer{height:32px;font-size:6px}.pause-button{font-size:6px}.bottom-row{margin-top:10px}.tip-card p{font-size:9px}.tip-label{font-size:7px}.site-footer{font-size:5px;letter-spacing:.04em;padding:10px 0 12px}}
@media(max-height:700px) and (min-width:721px){.topbar{height:58px}.intro-row{padding:16px 0 12px}h1{font-size:50px}.canvas-wrap{aspect-ratio:2.2}.game-controls{height:66px}.bottom-row{margin-top:10px}.site-footer{margin-top:12px}}
@media(prefers-reduced-motion:reduce){*,*:before,*:after{animation-duration:.01ms!important;transition-duration:.01ms!important;scroll-behavior:auto!important}}

(() => {
  'use strict';

  const canvas = document.getElementById('gameCanvas');
  const ctx = canvas.getContext('2d');
  const wrap = document.getElementById('canvasWrap');
  const overlay = document.getElementById('screenOverlay');
  const overlayContent = document.getElementById('overlayContent');
  const startButton = document.getElementById('startButton');
  const fireButton = document.getElementById('fireButton');
  const pauseButton = document.getElementById('pauseButton');
  const soundToggle = document.getElementById('soundToggle');
  const W = 960;
  const H = 490;
  const FLOOR = 423;
  const GRAVITY = 1550;
  const ROUND_LENGTH = 60;
  const keys = new Set();
  const held = new Set();
  const particles = [];
  const shots = [];
  const sparks = [];
  let phase = 'ready';
  let round = 1;
  let playerWins = 0;
  let rivalWins = 0;
  let timeLeft = ROUND_LENGTH;
  let lastTime = 0;
  let elapsed = 0;
  let playerFireAt = 0;
  let botFireAt = 0;
  let botJumpAt = 2;
  let botStrafeAt = 0;
  let botDirection = 1;
  let aim = -0.08;
  let soundOn = true;
  let audioContext = null;
  let roundTimeout = 0;
  let aimRepeat = 0;
  let screenShake = 0;

  const player = makeFighter('player');
  const rival = makeFighter('rival');

  function makeFighter(side) {
    return {
      side,
      x: side === 'player' ? 122 : 838,
      y: FLOOR,
      vx: 0,
      vy: 0,
      health: 100,
      grounded: true,
      face: side === 'player' ? 1 : -1,
      hitFlash: 0,
      bob: 0,
      trail: []
    };
  }

  function resize() {
    const rect = canvas.getBoundingClientRect();
    const dpr = Math.min(window.devicePixelRatio || 1, 2);
    canvas.width = Math.max(1, Math.round(rect.width * dpr));
    canvas.height = Math.max(1, Math.round(rect.height * dpr));
    ctx.setTransform(canvas.width / W, 0, 0, canvas.height / H, 0, 0);
    draw();
  }
  window.addEventListener('resize', resize, { passive: true });

  function resetFighters() {
    Object.assign(player, { x: 122, y: FLOOR, vx: 0, vy: 0, health: 100, grounded: true, hitFlash: 0, bob: 0, trail: [] });
    Object.assign(rival, { x: 838, y: FLOOR, vx: 0, vy: 0, health: 100, grounded: true, hitFlash: 0, bob: 0, trail: [] });
    aim = -0.08;
    shots.length = 0;
    particles.length = 0;
    sparks.length = 0;
    timeLeft = ROUND_LENGTH;
  }

  function setOverlay(type, winner) {
    overlay.classList.remove('hidden');
    if (type === 'ready') {
      overlayContent.innerHTML = '<div class="overlay-kicker"><span>01</span> READY PLAYER ONE</div><h2>STEP INTO<br><em>THE ARENA</em></h2><p>First to two round wins takes the match.<br>Jump, dodge, and send it back.</p><button class="primary-button" id="startButton"><span>START MATCH</span><b>↗</b></button><div class="overlay-foot"><span class="keycap">A</span><span class="keycap">D</span> MOVE <span class="foot-dot">·</span> <span class="keycap">W</span> JUMP <span class="foot-dot">·</span> <span class="keycap">↑</span><span class="keycap">↓</span> AIM <span class="foot-dot">·</span> <span class="keycap">SPACE</span> FIRE</div>';
      document.getElementById('startButton').addEventListener('click', startMatch);
    } else if (type === 'paused') {
      overlayContent.innerHTML = '<div class="overlay-kicker"><span>Ⅱ</span> MATCH PAUSED</div><h2>TAKE A<br><em>BREATHER.</em></h2><p>Your rival is waiting. The arena clock is stopped.</p><button class="primary-button" id="resumeButton"><span>RESUME MATCH</span><b>↗</b></button>';
      document.getElementById('resumeButton').addEventListener('click', resumeMatch);
    } else if (type === 'round') {
      const won = winner === 'player';
      overlayContent.innerHTML = `<div class="overlay-kicker"><span>ROUND ${String(round).padStart(2, '0')}</span> ${won ? 'ROUND WON' : 'ROUND LOST'}</div><h2>${won ? 'NICE<br><em>SHOT.</em>' : 'GET BACK<br><em>IN THERE.</em>'}</h2><p>${won ? 'You took the round. Keep the pressure on.' : 'The bot got this one. Reset and strike back.'}<br>Next round starts in a moment…</p><div class="overlay-foot">${playerWins} YOU <span class="foot-dot">·</span> ${rivalWins} PIXEL</div>`;
    } else {
      const won = winner === 'player';
      overlayContent.innerHTML = `<div class="overlay-kicker"><span>MATCH COMPLETE</span> ${won ? 'VICTORY' : 'DEFEAT'}</div><h2>${won ? 'ARENA<br><em>CHAMPION.</em>' : 'RUN IT<br><em>BACK?</em>'}</h2><p>${won ? 'Pixel has been sent back to the lobby.' : 'Every champion starts with a rematch.'}<br>Final score: ${playerWins} — ${rivalWins}</p><button class="primary-button" id="rematchButton"><span>PLAY AGAIN</span><b>↗</b></button><div class="overlay-foot">SECTOR 07 — MIDTOWN</div>`;
      document.getElementById('rematchButton').addEventListener('click', startMatch);
    }
  }

  function startMatch() {
    clearTimeout(roundTimeout);
    playerWins = 0;
    rivalWins = 0;
    round = 1;
    elapsed = 0;
    resetFighters();
    updateScoreboard();
    phase = 'playing';
    overlay.classList.add('hidden');
    pauseButton.innerHTML = '<span>Ⅱ</span> PAUSE';
    lastTime = performance.now();
    playTone(440, 0.06, 'triangle', 0.035);
  }

  function resumeMatch() {
    phase = 'playing';
    overlay.classList.add('hidden');
    pauseButton.innerHTML = '<span>Ⅱ</span> PAUSE';
    lastTime = performance.now();
  }

  function togglePause() {
    if (phase === 'playing') {
      phase = 'paused';
      held.clear();
      keys.clear();
      fireButton.classList.remove('firing');
      pauseButton.innerHTML = '<span>▶</span> RESUME';
      setOverlay('paused');
    } else if (phase === 'paused') resumeMatch();
  }
  pauseButton.addEventListener('click', togglePause);
  startButton.addEventListener('click', startMatch);

  function updateScoreboard() {
    document.getElementById('yourScore').textContent = playerWins;
    document.getElementById('rivalScore').textContent = rivalWins;
    document.getElementById('roundNumber').textContent = String(round).padStart(2, '0');
    const allPips = [
      ['youPip1', playerWins >= 1], ['rivalPip1', rivalWins >= 1],
      ['youPip2', playerWins >= 2], ['rivalPip2', rivalWins >= 2],
      ['youPip3', playerWins >= 3], ['rivalPip3', rivalWins >= 3]
    ];
    for (const [id, won] of allPips) {
      const pip = document.getElementById(id);
      pip.classList.toggle('won-you', won && id.startsWith('you'));
      pip.classList.toggle('won-rival', won && id.startsWith('rival'));
    }
  }

  function updateHealth() {
    document.getElementById('playerHealth').style.width = `${player.health}%`;
    document.getElementById('rivalHealth').style.width = `${rival.health}%`;
    document.getElementById('playerHealthText').textContent = Math.ceil(player.health);
    document.getElementById('rivalHealthText').textContent = Math.ceil(rival.health);
    document.getElementById('timer').textContent = timeLeft.toFixed(1);
  }

  function finishRound(winner) {
    if (phase !== 'playing') return;
    phase = 'roundover';
    held.clear();
    fireButton.classList.remove('firing');
    if (winner === 'player') playerWins++;
    else if (winner === 'rival') rivalWins++;
    updateScoreboard();
    const matchWinner = playerWins >= 2 ? 'player' : rivalWins >= 2 ? 'rival' : null;
    if (matchWinner) {
      setOverlay('match', matchWinner);
      return;
    }
    setOverlay('round', winner);
    roundTimeout = window.setTimeout(() => {
      round++;
      resetFighters();
      updateScoreboard();
      phase = 'playing';
      overlay.classList.add('hidden');
      lastTime = performance.now();
    }, 2400);
  }

  function jump(f) {
    if (phase !== 'playing' || !f.grounded) return;
    f.vy = -610;
    f.grounded = false;
    burst(f.x, f.y - 4, f.side === 'player' ? '#36d9ff' : '#ff4d9b', 8, 115);
    playTone(230, 0.08, 'triangle', 0.025);
  }

  function fire(f, angle) {
    if (phase !== 'playing') return;
    const direction = f.side === 'player' ? 1 : -1;
    const color = f.side === 'player' ? '#66edff' : '#ff72ae';
    const muzzleX = f.x + direction * 31;
    const muzzleY = f.y - 43 + Math.sin(elapsed * 8 + (f.side === 'player' ? 0 : 1)) * 1.5;
    const velocity = 660;
    const a = f.side === 'player' ? angle : Math.PI - angle;
    shots.push({ x: muzzleX, y: muzzleY, vx: Math.cos(a) * velocity, vy: Math.sin(a) * velocity, owner: f.side, color, life: 1.5, trail: [] });
    burst(muzzleX, muzzleY, color, 3, 70);
    playTone(f.side === 'player' ? 590 : 430, 0.055, 'square', f.side === 'player' ? 0.018 : 0.012);
  }

  function hit(target, shot) {
    target.health = Math.max(0, target.health - 12);
    target.hitFlash = 0.16;
    target.vx += shot.vx > 0 ? 56 : -56;
    screenShake = 4;
    burst(shot.x, shot.y, shot.color, 13, 165);
    playTone(125, 0.09, 'sawtooth', 0.035);
    if (target.health <= 0) finishRound(shot.owner);
  }

  function burst(x, y, color, count, speed) {
    for (let i = 0; i < count; i++) {
      const a = Math.random() * Math.PI * 2;
      const s = speed * (0.25 + Math.random() * 0.8);
      particles.push({ x, y, vx: Math.cos(a) * s, vy: Math.sin(a) * s, life: 0.25 + Math.random() * 0.42, max: 0.67, size: 1 + Math.random() * 2.4, color });
    }
  }

  function playTone(freq, duration, type = 'sine', volume = 0.02) {
    if (!soundOn) return;
    try {
      audioContext ||= new (window.AudioContext || window.webkitAudioContext)();
      if (audioContext.state === 'suspended') audioContext.resume();
      const oscillator = audioContext.createOscillator();
      const gain = audioContext.createGain();
      oscillator.type = type;
      oscillator.frequency.setValueAtTime(freq, audioContext.currentTime);
      oscillator.frequency.exponentialRampToValueAtTime(Math.max(45, freq * 0.55), audioContext.currentTime + duration);
      gain.gain.setValueAtTime(volume, audioContext.currentTime);
      gain.gain.exponentialRampToValueAtTime(0.001, audioContext.currentTime + duration);
      oscillator.connect(gain);
      gain.connect(audioContext.destination);
      oscillator.start();
      oscillator.stop(audioContext.currentTime + duration);
    } catch (_) { /* Audio is optional; gameplay must not depend on it. */ }
  }

  soundToggle.addEventListener('click', () => {
    soundOn = !soundOn;
    document.getElementById('soundIcon').textContent = soundOn ? '♫' : '♪̸';
    soundToggle.setAttribute('aria-label', soundOn ? 'Mute sound' : 'Enable sound');
    if (soundOn) playTone(520, 0.07, 'sine', 0.02);
  });

  document.querySelectorAll('[data-action]').forEach(button => {
    const action = button.dataset.action;
    button.addEventListener('pointerdown', event => {
      event.preventDefault();
      button.setPointerCapture?.(event.pointerId);
      button.classList.add('pressed');
      if (action === 'jump') jump(player);
      else held.add(action);
    });
    const release = event => {
      event.preventDefault();
      button.classList.remove('pressed');
      held.delete(action);
    };
    button.addEventListener('pointerup', release);
    button.addEventListener('pointercancel', release);
    button.addEventListener('lostpointercapture', release);
    button.addEventListener('contextmenu', event => event.preventDefault());
  });

  const stopFire = event => {
    if (event) event.preventDefault();
    held.delete('fire');
    fireButton.classList.remove('firing');
  };
  fireButton.addEventListener('pointerdown', event => {
    event.preventDefault();
    fireButton.setPointerCapture?.(event.pointerId);
    held.add('fire');
    fireButton.classList.add('firing');
  });
  fireButton.addEventListener('pointerup', stopFire);
  fireButton.addEventListener('pointercancel', stopFire);
  fireButton.addEventListener('lostpointercapture', stopFire);
  fireButton.addEventListener('contextmenu', event => event.preventDefault());

  window.addEventListener('keydown', event => {
    const key = event.key.toLowerCase();
    if ([' ', 'arrowup', 'arrowdown', 'arrowleft', 'arrowright'].includes(key)) event.preventDefault();
    keys.add(key);
    if ((key === 'w' || key === 'arrowup') && !event.repeat) jump(player);
    if (key === 'escape' || key === 'p') togglePause();
  });
  window.addEventListener('keyup', event => keys.delete(event.key.toLowerCase()));
  window.addEventListener('blur', () => {
    keys.clear(); held.clear(); fireButton.classList.remove('firing');
  });
  document.addEventListener('visibilitychange', () => {
    if (document.hidden && phase === 'playing') togglePause();
  });

  function isDown(action) {
    if (action === 'left') return held.has('left') || keys.has('a') || keys.has('arrowleft');
    if (action === 'right') return held.has('right') || keys.has('d') || keys.has('arrowright');
    if (action === 'aimUp') return held.has('aimUp') || keys.has('arrowup');
    if (action === 'aimDown') return held.has('aimDown') || keys.has('arrowdown');
    if (action === 'fire') return held.has('fire') || keys.has(' ');
    return false;
  }

  function updateFighter(f, dt, direction) {
    const wasGrounded = f.grounded;
    f.vy += GRAVITY * dt;
    f.y += f.vy * dt;
    if (f.y >= FLOOR) {
      f.y = FLOOR;
      f.vy = 0;
      f.grounded = true;
      if (!wasGrounded) burst(f.x, FLOOR - 2, f.side === 'player' ? '#36d9ff' : '#ff4d9b', 5, 65);
    } else f.grounded = false;
    f.x += f.vx * dt;
    f.vx *= Math.pow(0.001, dt);
    f.x = Math.max(75, Math.min(W - 75, f.x));
    f.bob += dt * (f.grounded ? 7 : 3);
    f.hitFlash = Math.max(0, f.hitFlash - dt);
    if (direction) f.trail.push({ x: f.x, y: f.y - 32, life: 0.2 });
    f.trail.forEach(t => t.life -= dt);
    f.trail = f.trail.filter(t => t.life > 0);
  }

  function update(dt) {
    elapsed += dt;
    timeLeft = Math.max(0, timeLeft - dt);
    if (isDown('left')) player.vx -= 1100 * dt;
    if (isDown('right')) player.vx += 1100 * dt;
    player.vx = Math.max(-255, Math.min(255, player.vx));
    if (isDown('aimUp')) aim = Math.max(-0.75, aim - 1.25 * dt);
    if (isDown('aimDown')) aim = Math.min(0.68, aim + 1.25 * dt);

    if (elapsed >= botStrafeAt) {
      botDirection = Math.random() < 0.5 ? -1 : 1;
      botStrafeAt = elapsed + 1.1 + Math.random() * 1.8;
    }
    const botHome = 838;
    const botTarget = Math.max(710, Math.min(884, botHome + botDirection * 72));
    rival.vx += Math.sign(botTarget - rival.x) * 620 * dt;
    rival.vx = Math.max(-190, Math.min(190, rival.vx));
    if (elapsed >= botJumpAt && rival.grounded) {
      if (Math.random() < 0.76) jump(rival);
      botJumpAt = elapsed + 1.7 + Math.random() * 2.3;
    }

    updateFighter(player, dt, Math.abs(player.vx) > 40);
    updateFighter(rival, dt, Math.abs(rival.vx) > 40);

    if (isDown('fire') && elapsed >= playerFireAt) {
      fire(player, aim);
      playerFireAt = elapsed + 0.29;
    }
    if (elapsed >= botFireAt) {
      const dy = (player.y - rival.y) - rival.vy * 0.12;
      const distance = Math.max(1, rival.x - player.x);
      const botAim = Math.atan2(-dy, distance) + (Math.random() - 0.5) * 0.14;
      fire(rival, botAim);
      botFireAt = elapsed + (0.57 + Math.random() * 0.34);
    }

    for (let i = shots.length - 1; i >= 0; i--) {
      const s = shots[i];
      s.x += s.vx * dt;
      s.y += s.vy * dt;
      s.life -= dt;
      s.trail.push({ x: s.x, y: s.y, life: 0.16 });
      s.trail.forEach(t => t.life -= dt);
      s.trail = s.trail.filter(t => t.life > 0);
      const target = s.owner === 'player' ? rival : player;
      const bodyY = target.y - 42;
      if (Math.abs(s.x - target.x) < 25 && Math.abs(s.y - bodyY) < 33) {
        hit(target, s);
        shots.splice(i, 1);
        continue;
      }
      if (s.life <= 0 || s.x < -15 || s.x > W + 15 || s.y < 15 || s.y > FLOOR + 30) shots.splice(i, 1);
    }

    for (let i = particles.length - 1; i >= 0; i--) {
      const p = particles[i];
      p.x += p.vx * dt; p.y += p.vy * dt;
      p.vx *= Math.pow(0.05, dt); p.vy *= Math.pow(0.05, dt);
      p.life -= dt;
      if (p.life <= 0) particles.splice(i, 1);
    }
    screenShake = Math.max(0, screenShake - 28 * dt);
    updateHealth();
    if (phase === 'playing' && timeLeft <= 0) {
      finishRound(player.health === rival.health ? 'draw' : player.health > rival.health ? 'player' : 'rival');
    }
  }

  function drawBackground() {
    const gradient = ctx.createLinearGradient(0, 0, 0, H);
    gradient.addColorStop(0, '#111827');
    gradient.addColorStop(0.62, '#172238');
    gradient.addColorStop(1, '#1b2635');
    ctx.fillStyle = gradient;
    ctx.fillRect(0, 0, W, H);

    ctx.save();
    ctx.globalAlpha = 0.45;
    for (let i = 0; i < 38; i++) {
      const x = ((i * 127 + 21) % W);
      const y = 35 + ((i * 71) % 235);
      ctx.fillStyle = i % 4 === 0 ? '#b7f36b' : '#93a5c4';
      ctx.globalAlpha = 0.12 + ((i * 17) % 30) / 100;
      ctx.fillRect(x, y, i % 5 === 0 ? 2 : 1, i % 7 === 0 ? 2 : 1);
    }
    ctx.globalAlpha = 1;
    const buildings = [
      [0, 210, 115, 214], [93, 164, 96, 260], [176, 202, 130, 222], [287, 146, 111, 278],
      [397, 190, 110, 234], [510, 157, 127, 267], [633, 209, 98, 215], [723, 170, 114, 254], [830, 194, 130, 230]
    ];
    buildings.forEach(([x, y, w, h], index) => {
      ctx.fillStyle = index % 2 ? '#202c40' : '#1c2739';
      ctx.fillRect(x, y, w, h);
      ctx.fillStyle = '#28364a';
      ctx.fillRect(x + 7, y + 8, 2, h - 12);
      for (let wx = x + 15; wx < x + w - 9; wx += 18) {
        for (let wy = y + 15; wy < FLOOR - 15; wy += 22) {
          const lit = ((Math.floor(wx / 18) * 7 + Math.floor(wy / 22) * 3 + index) % 6) < 2;
          ctx.fillStyle = lit ? (index % 2 ? '#45544e' : '#344c5a') : '#263246';
          ctx.fillRect(wx, wy, 6, 9);
        }
      }
    });
    ctx.restore();

    // Neon signage and skyline guide lines.
    ctx.save();
    ctx.globalAlpha = 0.62;
    ctx.shadowBlur = 12;
    ctx.shadowColor = '#ff4d9b';
    ctx.strokeStyle = '#ad3e72';
    ctx.lineWidth = 2;
    ctx.strokeRect(72, 254, 94, 29);
    ctx.fillStyle = '#f168a4';
    ctx.font = 'bold 11px monospace';
    ctx.fillText('NIGHT / CITY', 81, 273);
    ctx.shadowColor = '#36d9ff';
    ctx.strokeStyle = '#30829a';
    ctx.strokeRect(780, 235, 113, 34);
    ctx.fillStyle = '#68dff5';
    ctx.fillText('SECTOR 07', 793, 257);
    ctx.restore();

    ctx.fillStyle = '#17202c';
    ctx.fillRect(0, FLOOR, W, H - FLOOR);
    const floorGrad = ctx.createLinearGradient(0, FLOOR, 0, H);
    floorGrad.addColorStop(0, '#253344'); floorGrad.addColorStop(1, '#131b27');
    ctx.fillStyle = floorGrad;
    ctx.fillRect(0, FLOOR, W, H - FLOOR);
    ctx.strokeStyle = '#5c7e7d';
    ctx.globalAlpha = 0.46;
    ctx.lineWidth = 1;
    ctx.beginPath(); ctx.moveTo(0, FLOOR); ctx.lineTo(W, FLOOR); ctx.stroke();
    ctx.globalAlpha = 0.15;
    for (let i = -5; i <= 5; i++) {
      ctx.beginPath(); ctx.moveTo(W / 2 + i * 58, FLOOR); ctx.lineTo(W / 2 + i * 105, H); ctx.stroke();
    }
    for (let y = FLOOR + 19; y < H; y += 24) {
      ctx.beginPath(); ctx.moveTo(0, y); ctx.lineTo(W, y); ctx.stroke();
    }
    ctx.globalAlpha = 1;
    // Central arena marker.
    ctx.fillStyle = '#9db7b7';
    ctx.globalAlpha = 0.55;
    ctx.fillRect(W / 2 - 1, FLOOR - 7, 2, 7);
    ctx.fillRect(W / 2 - 17, FLOOR - 1, 34, 1);
    ctx.globalAlpha = 1;
  }

  function drawFighter(f) {
    const isPlayer = f.side === 'player';
    const main = isPlayer ? '#36d9ff' : '#ff4d9b';
    const dark = isPlayer ? '#126078' : '#73274f';
    const pale = isPlayer ? '#b8f5ff' : '#ffc3dc';
    const dir = isPlayer ? 1 : -1;
    const moving = Math.abs(f.vx) > 25 && f.grounded;
    const run = moving ? Math.sin(f.bob * 2) * 5 : 0;
    const lift = f.grounded ? Math.sin(f.bob) * 1.3 : 0;
    ctx.save();
    // Foot shadow.
    ctx.globalAlpha = Math.max(0.12, 0.32 - (FLOOR - f.y) / 900);
    ctx.fillStyle = '#050810';
    ctx.beginPath(); ctx.ellipse(f.x, FLOOR + 2, f.grounded ? 25 : 18, f.grounded ? 5 : 3, 0, 0, Math.PI * 2); ctx.fill();
    ctx.globalAlpha = 1;
    f.trail.forEach(t => {
      ctx.globalAlpha = Math.max(0, t.life / 0.2) * 0.18;
      ctx.fillStyle = main;
      ctx.fillRect(t.x - 12, t.y - 16, 24, 31);
    });
    ctx.globalAlpha = 1;
    ctx.translate(f.x, f.y + lift);
    ctx.scale(dir, 1);
    ctx.shadowColor = main;
    ctx.shadowBlur = 13;
    if (f.hitFlash > 0) ctx.globalAlpha = 0.55 + Math.sin(f.hitFlash * 90) * 0.45;

    // Legs and boots.
    ctx.fillStyle = dark;
    ctx.beginPath(); ctx.moveTo(-12, -20); ctx.lineTo(-2, -20); ctx.lineTo(-4 + run, -4); ctx.lineTo(-15 + run, -4); ctx.closePath(); ctx.fill();
    ctx.beginPath(); ctx.moveTo(3, -20); ctx.lineTo(13, -20); ctx.lineTo(18 - run, -4); ctx.lineTo(7 - run, -4); ctx.closePath(); ctx.fill();
    ctx.fillStyle = main;
    ctx.fillRect(-18 + run, -5, 15, 5);
    ctx.fillRect(5 - run, -5, 15, 5);

    // Body armor.
    ctx.fillStyle = dark;
    ctx.beginPath(); ctx.moveTo(-16, -39); ctx.lineTo(12, -40); ctx.lineTo(19, -20); ctx.lineTo(10, -14); ctx.lineTo(-13, -17); ctx.lineTo(-20, -27); ctx.closePath(); ctx.fill();
    ctx.fillStyle = main;
    ctx.globalAlpha *= 0.8;
    ctx.beginPath(); ctx.moveTo(-13, -36); ctx.lineTo(9, -36); ctx.lineTo(14, -24); ctx.lineTo(7, -20); ctx.lineTo(-11, -22); ctx.closePath(); ctx.fill();
    ctx.globalAlpha = 1;
    ctx.fillStyle = pale;
    ctx.fillRect(-3, -33, 11, 3);
    ctx.fillStyle = '#101827';
    ctx.fillRect(-9, -30, 7, 5);

    // Head, visor, and ear armor.
    ctx.fillStyle = dark;
    ctx.beginPath(); ctx.moveTo(-12, -61); ctx.lineTo(5, -63); ctx.lineTo(16, -54); ctx.lineTo(14, -39); ctx.lineTo(-6, -37); ctx.lineTo(-16, -45); ctx.closePath(); ctx.fill();
    ctx.fillStyle = pale;
    ctx.beginPath(); ctx.moveTo(-4, -57); ctx.lineTo(9, -57); ctx.lineTo(13, -50); ctx.lineTo(3, -47); ctx.lineTo(-7, -49); ctx.closePath(); ctx.fill();
    ctx.fillStyle = main;
    ctx.fillRect(4, -53, 8, 3);
    ctx.fillStyle = dark;
    ctx.fillRect(-18, -52, 4, 10);
    // Back-mounted pack.
    ctx.fillStyle = '#29364a';
    ctx.fillRect(-21, -37, 7, 16);
    ctx.fillStyle = main;
    ctx.globalAlpha = 0.9;
    ctx.fillRect(-20, -34, 2, 8);
    ctx.globalAlpha = 1;

    // Weapon pointed forward.
    ctx.fillStyle = '#b7c4d2';
    ctx.fillRect(7, -35, 29, 7);
    ctx.fillStyle = '#526177';
    ctx.fillRect(14, -37, 16, 2);
    ctx.fillStyle = main;
    ctx.fillRect(34, -34, 5, 4);
    ctx.fillStyle = '#151c28';
    ctx.fillRect(16, -28, 4, 7);
    if (f.hitFlash > 0) ctx.globalAlpha = 1;
    ctx.restore();
  }

  function draw() {
    if (!ctx) return;
    ctx.save();
    if (screenShake > 0) ctx.translate((Math.random() - 0.5) * screenShake, (Math.random() - 0.5) * screenShake);
    drawBackground();

    // Arena floor lights.
    for (let i = 0; i < 12; i++) {
      const x = (i * 88 + 19) % W;
      ctx.globalAlpha = 0.18 + Math.sin(elapsed * 2 + i) * 0.08;
      ctx.fillStyle = i % 2 ? '#ff4d9b' : '#36d9ff';
      ctx.fillRect(x, FLOOR + 9, 28, 2);
    }
    ctx.globalAlpha = 1;

    // Projectile trails.
    shots.forEach(s => {
      s.trail.forEach(t => {
        ctx.globalAlpha = Math.max(0, t.life / 0.16) * 0.38;
        ctx.fillStyle = s.color;
        ctx.beginPath(); ctx.arc(t.x, t.y, 2.5, 0, Math.PI * 2); ctx.fill();
      });
      ctx.globalAlpha = 1;
      ctx.save();
      ctx.shadowColor = s.color; ctx.shadowBlur = 15;
      ctx.fillStyle = '#fff';
      ctx.beginPath(); ctx.arc(s.x, s.y, 3.2, 0, Math.PI * 2); ctx.fill();
      ctx.fillStyle = s.color;
      ctx.beginPath(); ctx.ellipse(s.x - Math.sign(s.vx) * 5, s.y, 7, 2, 0, 0, Math.PI * 2); ctx.fill();
      ctx.restore();
    });

    drawFighter(player);
    drawFighter(rival);

    // Aim guide is subtle and only shown while lining up a shot.
    if (phase === 'playing' && (isDown('aimUp') || isDown('aimDown'))) {
      ctx.save();
      ctx.setLineDash([4, 7]); ctx.strokeStyle = '#b7f36b'; ctx.globalAlpha = 0.4; ctx.lineWidth = 1;
      ctx.beginPath(); ctx.moveTo(player.x + 37, player.y - 43); ctx.lineTo(player.x + 220 * Math.cos(aim), player.y - 43 + 220 * Math.sin(aim)); ctx.stroke();
      ctx.restore();
    }

    particles.forEach(p => {
      ctx.globalAlpha = Math.max(0, p.life / p.max);
      ctx.fillStyle = p.color;
      ctx.shadowColor = p.color; ctx.shadowBlur = 8;
      ctx.fillRect(p.x, p.y, p.size, p.size);
    });
    ctx.globalAlpha = 1; ctx.shadowBlur = 0;

    // Active player aim reticle.
    if (phase === 'playing') {
      const rx = player.x + 240 * Math.cos(aim);
      const ry = player.y - 43 + 240 * Math.sin(aim);
      ctx.save(); ctx.globalAlpha = 0.58; ctx.strokeStyle = '#b7f36b'; ctx.lineWidth = 1;
      ctx.beginPath(); ctx.arc(rx, ry, 7, 0, Math.PI * 2); ctx.moveTo(rx - 11, ry); ctx.lineTo(rx - 4, ry); ctx.moveTo(rx + 4, ry); ctx.lineTo(rx + 11, ry); ctx.moveTo(rx, ry - 11); ctx.lineTo(rx, ry - 4); ctx.moveTo(rx, ry + 4); ctx.lineTo(rx, ry + 11); ctx.stroke();
      ctx.restore();
    }
    ctx.restore();
  }

  function frame(now) {
    const dt = Math.min(0.033, Math.max(0, (now - (lastTime || now)) / 1000));
    lastTime = now;
    if (phase === 'playing') update(dt);
    else {
      elapsed += dt * 0.35;
      for (let i = particles.length - 1; i >= 0; i--) {
        const p = particles[i]; p.x += p.vx * dt; p.y += p.vy * dt; p.life -= dt;
        if (p.life <= 0) particles.splice(i, 1);
      }
    }
    draw();
    requestAnimationFrame(frame);
  }

  updateScoreboard();
  updateHealth();
  resize();
  requestAnimationFrame(frame);
})();

