.control-button small{font-size:6px;color:#9099a8;letter-spacing:.08em}
.jump-button{margin-left:4px;border-color:#36414c;background:#202a30}
.jump-button span{color:var(--green)}
.game-controls{height:73px}
.game-controls{height:66px;gap:5px}
.move-controls{gap:4px}
.control-button small{font-size:5px}
.jump-button{margin-left:1px}
.game-controls{height:66px}

.top-tag,.eyebrow,.fighter-sub,.round-label,.health-meta,.canvas-hud,.game-footer,.tip-label,.controls-legend,.site-footer,.overlay-kicker,.overlay-foot,.control-button small,.aim-label{font-family:var(--mono);letter-spacing:.08em}
.game-controls{height:82px;display:flex;align-items:center;justify-content:space-between;gap:10px}
.move-controls,.aim-controls{display:flex;align-items:center;gap:7px}
.control-button{border:1px solid #333b4d;background:#202635;color:#dce1e7;border-radius:7px;cursor:pointer;touch-action:none;user-select:none;-webkit-user-select:none;transition:background .12s,border .12s,transform .12s}
.control-button:active,.control-button.pressed{background:#354256;border-color:var(--green);transform:scale(.97)}
.control-button small{font-size:6px;color:#9099a8;letter-spacing:.08em}
.jump-button{margin-left:4px;border-color:#36414c;background:#202a30}
.jump-button span{color:var(--green)}

.move-button{height:48px;width:51px;display:flex;flex-direction:column;justify-content:center;align-items:center;gap:0}
.move-button span{font-size:19px;line-height:20px}
.aim-button{height:32px;width:35px;font-size:16px;line-height:1}
.fire-button{height:49px;min-width:155px;border:1px solid #a93c6b;border-radius:6px;background:linear-gradient(110deg,#5b2040,#351a31);color:#ffd7e8;display:flex;justify-content:center;align-items:center;gap:9px;font:700 9px var(--mono);letter-spacing:.09em;cursor:pointer;touch-action:none;user-select:none;box-shadow:inset 0 0 18px #ff4d9b0a;transition:.15s}
.fire-button .fire-icon{font-size:17px;color:var(--pink)}
.fire-button i{position:absolute;display:none}
.fire-button:hover,.fire-button.firing{background:linear-gradient(110deg,#9d3267,#5a204e);border-color:#ff75b1;box-shadow:0 0 18px #ff4d9b30}
.fire-button.firing .fire-icon{animation:spin .6s linear infinite}

